class AuthenticationManager { int ttl;Map<String,Integer> expiry=new HashMap<>();public AuthenticationManager(int timeToLive){ttl=timeToLive;}public void generate(String tokenId,int currentTime){expiry.put(tokenId,currentTime+ttl);}public void renew(String tokenId,int currentTime){if(expiry.getOrDefault(tokenId,0)>currentTime)expiry.put(tokenId,currentTime+ttl);}public int countUnexpiredTokens(int currentTime){int count=0;for(int time:expiry.values())if(time>currentTime)count++;return count;} }
